import { ControlBaselines, FrameworkControlDefinition, FrameworkDomainInfo } from '../../types/framework';
import catalogFile from './nist80053/catalog.generated.json';
import type { GeneratedCatalogFile, GeneratedControl } from './nist80053/types';
import { collapseTags } from './parameters';
import { NIST_800_53_CURATED_CONTROLS } from './nist80053Curated';

/**
 * NIST SP 800-53 Rev. 5: every control and control enhancement (SP 800-53 Rel. 5.x, OSCAL), generated by
 * scripts/generateNist80053.ts from NIST's own data. Each control carries its official statement with the
 * [Assignment: ...] / [Selection: ...] tags (so its organization-defined parameters are found by the parser in
 * parameters.ts), its guidance, and the SP 800-53B baselines (Low, Moderate, High, Privacy) that include it. The
 * SP 800-53A assessment objectives are large and are loaded separately (see nist80053/objectives*.ts).
 */
const FAMILY_DETAILS: Record<string, FrameworkDomainInfo> = {
  AC: { code: 'AC', name: 'Access Control', description: 'Account management, access enforcement, remote & wireless access, least privilege.', totalControls: 16, iconName: 'ShieldCheck', color: '#0284c7' },
  AT: { code: 'AT', name: 'Awareness and Training', description: 'Cyber awareness, role-based training, security literacy, and record keeping.', totalControls: 4, iconName: 'GraduationCap', color: '#6366f1' },
  AU: { code: 'AU', name: 'Audit and Accountability', description: 'Event logging, audit reduction, non-repudiation, and audit storage integrity.', totalControls: 12, iconName: 'FileText', color: '#a855f7' },
  CA: { code: 'CA', name: 'Assessment, Authorization & Monitoring', description: 'Continuous monitoring, vulnerability assessments, and plan of action.', totalControls: 5, iconName: 'ClipboardCheck', color: '#06b6d4' },
  CM: { code: 'CM', name: 'Configuration Management', description: 'Hardened baselines, change control, impact analysis, and inventory management.', totalControls: 11, iconName: 'Settings', color: '#ec4899' },
  CP: { code: 'CP', name: 'Contingency Planning', description: 'Business continuity, disaster recovery, system backups, and resilience testing.', totalControls: 8, iconName: 'LifeBuoy', color: '#10b981' },
  IA: { code: 'IA', name: 'Identification and Authentication', description: 'User identification, authenticator management, MFA, and cryptographic tokens.', totalControls: 10, iconName: 'KeyRound', color: '#8b5cf6' },
  IR: { code: 'IR', name: 'Incident Response', description: 'Preparation, detection, containment, investigation, reporting, and recovery.', totalControls: 8, iconName: 'AlertOctagon', color: '#ef4444' },
  MA: { code: 'MA', name: 'Maintenance', description: 'Controlled maintenance, tool inspection, sanitization, and remote session supervision.', totalControls: 6, iconName: 'Wrench', color: '#f97316' },
  MP: { code: 'MP', name: 'Media Protection', description: 'Media storage, physical transport, sanitization, and cryptographically marked drives.', totalControls: 7, iconName: 'HardDriveDownload', color: '#eab308' },
  PE: { code: 'PE', name: 'Physical and Environmental Protection', description: 'Perimeter access, visitor control, power, fire suppression, and environmental monitoring.', totalControls: 10, iconName: 'Building2', color: '#f59e0b' },
  PL: { code: 'PL', name: 'Planning', description: 'System security and privacy planning, rules of behavior, and boundary definition.', totalControls: 3, iconName: 'BookOpen', color: '#64748b' },
  PS: { code: 'PS', name: 'Personnel Security', description: 'Screening, termination, transfer, access agreements, and third-party personnel.', totalControls: 6, iconName: 'Users', color: '#14b8a6' },
  RA: { code: 'RA', name: 'Risk Assessment', description: 'Risk identification, threat modeling, vulnerability scanning, and supply chain review.', totalControls: 4, iconName: 'TrendingDown', color: '#84cc16' },
  SA: { code: 'SA', name: 'System and Services Acquisition', description: 'Supply chain risk management, software development lifecycles, and third-party vetting.', totalControls: 6, iconName: 'ShoppingBag', color: '#0ea5e9' },
  SC: { code: 'SC', name: 'System and Communications Protection', description: 'Boundary protection, cryptography, denial of service mitigation, and session integrity.', totalControls: 18, iconName: 'Network', color: '#059669' },
  SI: { code: 'SI', name: 'System and Information Integrity', description: 'Flaw remediation, malicious code defense, system monitoring, and spam protection.', totalControls: 9, iconName: 'CheckCircle2', color: '#3b82f6' },
  PM: { code: 'PM', name: 'Program Management', description: 'Organization-wide information security program plan, resources, risk management strategy, and continuous monitoring.', totalControls: 2, iconName: 'Briefcase', color: '#64748b' },
  PT: { code: 'PT', name: 'PII Processing and Transparency', description: 'Authority to process personally identifiable information (PII), privacy notices, and consent management.', totalControls: 3, iconName: 'Eye', color: '#14b8a6' },
  SR: { code: 'SR', name: 'Supply Chain Risk Management', description: 'Controls and inspection throughout the supply chain lifecycle of hardware and software.', totalControls: 4, iconName: 'Truck', color: '#d97706' },
};

const catalog = catalogFile as unknown as GeneratedCatalogFile;
const FAMILY_TITLES = new Map(catalog.families.map((f) => [f.code, f.title]));
const curatedById = new Map(NIST_800_53_CURATED_CONTROLS.map((c) => [c.id, c]));

const NETWORK_BOUNDARY = /^(SC-7|AC-17|SC-8)(\(|$)/;

const baselinesOf = (g: GeneratedControl): ControlBaselines => ({ low: g.baselines.includes('L'), moderate: g.baselines.includes('M'), high: g.baselines.includes('H'), privacy: g.privacy });

/** A short readable summary: the statement without its list markers, with each parameter tag reduced to its description. */
export function summarizeStatement(statement: string, max = 260): string {
  const text = collapseTags(statement).replace(/^\s*(?:\(?[a-z0-9]{1,3}[.)]\s+)/gm, '').replace(/\s+/g, ' ').trim();
  return text.length <= max ? text : `${text.slice(0, max - 1).trimEnd()}…`;
}

function toDefinition(g: GeneratedControl): FrameworkControlDefinition {
  const curated = curatedById.get(g.id);
  const baselines = baselinesOf(g);
  const domainName = FAMILY_TITLES.get(g.family) ?? g.family;
  return {
    id: g.id,
    title: g.title,
    statement: g.statement,
    framework: 'NIST_800_53_REV5',
    domain: g.family,
    domainName,
    authorityReference: `NIST SP 800-53 Rev 5 ${g.id}`,
    plainEnglishSummary: curated?.plainEnglishSummary ?? summarizeStatement(g.statement),
    discussion: g.guidance,
    assessmentObjectives: [],
    auditorChecklist: [],
    controlKind: g.kind,
    ...(g.parent ? { parentControlId: g.parent } : {}),
    baselines,
    baselineImpact: baselines.low ? 'LOW' : baselines.moderate ? 'MODERATE' : baselines.high ? 'HIGH' : undefined,
    relatedControls: g.related,
    nonNetworkedApplicable: curated?.nonNetworkedApplicable === false ? false : !NETWORK_BOUNDARY.test(g.id),
    requiresWireless: /^AC-18(\(|$)/.test(g.id) || undefined,
    requiresMobile: /^AC-19(\(|$)/.test(g.id) || undefined,
    requiresPii: g.family === 'PT' || undefined,
    ...(curated?.mappings ? { mappings: curated.mappings } : {}),
  };
}

export const NIST_800_53_CONTROLS: FrameworkControlDefinition[] = catalog.controls.map(toDefinition);

const familyCounts = new Map<string, number>();
for (const c of NIST_800_53_CONTROLS) familyCounts.set(c.domain, (familyCounts.get(c.domain) ?? 0) + 1);

/** The twenty control families, with the number of controls and enhancements in each. */
export const NIST_800_53_DOMAINS: Record<string, FrameworkDomainInfo> = Object.fromEntries(
  catalog.families.map((f) => {
    const details = FAMILY_DETAILS[f.code];
    return [f.code, { ...(details ?? { code: f.code, description: f.title, iconName: 'Shield', color: '#64748b' }), name: f.title, totalControls: familyCounts.get(f.code) ?? 0 }];
  })
);

/** Provenance of the generated data (source URLs and hashes). */
export const NIST_800_53_SOURCE = catalog.meta;
